insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000001', '〜たことがある', 'N4', 'experience', 'Đã từng làm việc gì', 'Động từ thể た + ことがある', 'Diễn tả trải nghiệm đã xảy ra trước thời điểm nói.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000001', '日本へ行ったことがあります。', 'Tôi đã từng đến Nhật Bản.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000002', '〜たい', 'N5', 'desire', 'Muốn làm việc gì', 'Động từ thể ます bỏ ます + たい', 'Diễn tả mong muốn thực hiện một hành động của người nói.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000002', '日本語を勉強したいです。', 'Tôi muốn học tiếng Nhật.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000003', '〜ている', 'N5', 'aspect', 'Đang thực hiện hành động', 'Động từ thể て + いる', 'Trong ví dụ này, diễn tả một hành động đang diễn ra.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000003', '本を読んでいます。', 'Tôi đang đọc sách.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000004', '〜てもいい', 'N5', 'permission', 'Được phép làm việc gì', 'Động từ thể て + もいい', 'Hỏi hoặc cho phép một hành động; ví dụ dùng câu hỏi lịch sự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000004', 'ここで写真を撮ってもいいですか。', 'Tôi có thể chụp ảnh ở đây không?', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000005', '〜てはいけない', 'N5', 'prohibition', 'Không được làm việc gì', 'Động từ thể て + はいけない', 'Nêu điều cấm; cách nói có thể mạnh tùy quan hệ và tình huống.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000005', 'ここでタバコを吸ってはいけません。', 'Không được hút thuốc ở đây.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000006', '〜なければならない', 'N4', 'obligation', 'Phải làm việc gì', 'Động từ thể ない bỏ い + ければならない', 'Nêu nghĩa vụ; ví dụ しない chuyển thành しなければならない.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000006', '明日までに宿題をしなければなりません。', 'Tôi phải làm bài tập trước hạn ngày mai.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000007', '〜なくてもいい', 'N4', 'permission', 'Không cần làm việc gì', 'Động từ thể ない bỏ い + くてもいい', 'Diễn tả không bắt buộc làm, không phải lệnh cấm làm.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000007', '今日は学校へ行かなくてもいいです。', 'Hôm nay không cần đến trường.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000008', '〜つもりだ', 'N4', 'intention', 'Dự định làm việc gì', 'Động từ thể từ điển + つもりだ', 'Diễn tả dự định của người nói; ví dụ dùng dạng lịch sự つもりです.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000008', '来年、日本へ行くつもりです。', 'Tôi dự định đến Nhật Bản vào năm sau.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000009', '〜ながら', 'N4', 'simultaneous', 'Vừa làm việc này vừa làm việc khác', 'Động từ thể ます bỏ ます + ながら', 'Hai hành động cùng chủ thể; mệnh đề sau là hành động chính trong ví dụ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000009', '音楽を聞きながら勉強します。', 'Tôi vừa nghe nhạc vừa học.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000010', '〜より〜のほうが', 'N5', 'comparison', 'So với A thì B hơn về một mặt', 'A より B のほうが + tính từ', 'So sánh hai đối tượng theo đặc điểm được nêu, không khái quát mọi mặt.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000010', 'バスより電車のほうが速いです。', 'So với xe buýt, tàu điện nhanh hơn.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000011', '〜ことができる', 'N4', 'ability', 'Có thể làm việc gì', 'Động từ thể từ điển + ことができる', 'Trong ví dụ, diễn tả năng lực thực hiện một hành động.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000011', '私は日本語を話すことができます。', 'Tôi có thể nói tiếng Nhật.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000012', '〜てから', 'N5', 'sequence', 'Sau khi làm A thì làm B', 'Động từ thể て + から、B', 'Diễn tả thứ tự hành động A rồi B.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000012', '手を洗ってから、ご飯を食べます。', 'Tôi rửa tay rồi mới ăn cơm.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000013', '〜は〜です', 'N5', 'particles', 'A là B (khẳng định lịch sự)', 'Danh từ A + は + Danh từ B + です', 'Giới thiệu chủ đề A và khẳng định tính chất hoặc danh phận B một cách lịch sự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000013', '私は学生です。', 'Tôi là sinh viên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000013', '明日は日曜日です。', 'Ngày mai là Chủ nhật.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000014', '〜ではありません', 'N5', 'particles', 'Không phải là ~ (phủ định lịch sự)', 'Danh từ / Tính từ な + ではありません（じゃありません）', 'Phủ định danh từ hoặc tính từ đuôi な trong văn nói/viết lịch sự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000014', '私は先生ではありません。', 'Tôi không phải là giáo viên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000014', 'ここは図書館ではありません。', 'Đây không phải là thư viện.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000015', '〜か', 'N5', 'particles', 'Câu hỏi lịch sự (có phải ~ không?)', 'Câu lịch sự (〜です / 〜ます) + か', 'Đặt か ở cuối câu để chuyển thành câu nghi vấn lịch sự, không cần thêm dấu hỏi chấm khi viết chuẩn.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000015', 'お名前は何ですか。', 'Tên bạn là gì vậy?', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000015', '毎朝コーヒーを飲みますか。', 'Mỗi sáng bạn có uống cà phê không?', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000016', '〜の〜', 'N5', 'particles', 'Của ~ / bổ nghĩa giữa hai danh từ', 'Danh từ 1 + の + Danh từ 2', 'Nối hai danh từ để biểu thị sở hữu, nguồn gốc hoặc nội dung của danh từ đứng sau.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000016', 'これは私の本です。', 'Đây là sách của tôi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000016', '日本語の先生と話しました。', 'Tôi đã nói chuyện với thầy giáo tiếng Nhật.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000017', '〜も', 'N5', 'particles', 'Cũng ~ (thêm đối tượng tương đồng)', 'Danh từ + も', 'Thay cho は hoặc が khi muốn diễn tả đối tượng khác cũng có trạng thái hay hành động tương tự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000017', '私も学生です。', 'Tôi cũng là sinh viên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000017', '昨日も雨が降りました。', 'Hôm qua trời cũng mưa.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000018', '〜を', 'N5', 'particles', 'Tân ngữ trực tiếp của hành động', 'Danh từ + を + Ngoại động từ', 'Chỉ đối tượng chịu tác động trực tiếp của hành động.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000018', '朝ご飯を食べます。', 'Tôi ăn bữa sáng.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000018', '毎日日本語を勉強します。', 'Mỗi ngày tôi học tiếng Nhật.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000019', '〜に（時間）', 'N5', 'particles', 'Vào lúc ~ (mốc thời gian cụ thể)', 'Danh từ thời gian có số cụ thể + に + Động từ', 'Dùng cho giờ, ngày, tháng, năm, thứ; không dùng sau 今日, 明日, 毎日.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000019', '毎朝六時に起きます。', 'Mỗi sáng tôi dậy lúc 6 giờ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000019', '十月に日本へ行きます。', 'Tháng 10 tôi sẽ đi Nhật.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000020', '〜に・へ（方向）', 'N5', 'particles', 'Đi về hướng / tới địa điểm ~', 'Địa điểm + に / へ + 行きます・来ます・帰ります', 'Biểu thị điểm đến hoặc phương hướng với các động từ di chuyển.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000020', '来週、東京へ行きます。', 'Tuần sau tôi sẽ đi Tokyo.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000020', '五時に家へ帰ります。', '5 giờ tôi về nhà.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000021', '〜で（場所）', 'N5', 'particles', 'Tại địa điểm ~ (nơi diễn ra hành động)', 'Địa điểm + で + Hành động', 'Chỉ địa điểm nơi một hành động cụ thể diễn ra; khác với に dùng cho tồn tại hoặc đích đến.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000021', '食堂で昼ご飯を食べます。', 'Tôi ăn trưa ở nhà ăn.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000021', '駅で新聞を買いました。', 'Tôi đã mua báo ở nhà ga.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000022', '〜で（手段・道具）', 'N5', 'particles', 'Bằng phương tiện / công cụ / ngôn ngữ ~', 'Phương tiện / Công cụ / Ngôn ngữ + で + Động từ', 'Nêu cách thức, phương tiện đi lại, dụng cụ hoặc ngôn ngữ thực hiện hành động.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000022', '電車で会社へ行きます。', 'Tôi đi đến công ty bằng tàu điện.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000022', 'はしでご飯を食べます。', 'Tôi ăn cơm bằng đũa.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000023', '〜と（共同）', 'N5', 'particles', 'Cùng với ai / và (liệt kê đầy đủ)', 'Người + と + Hành động / Danh từ A + と + Danh từ B', 'Diễn tả đối tượng cùng thực hiện hành động, hoặc nối trọn vẹn các danh từ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000023', '友達と映画を見ました。', 'Tôi đã xem phim cùng bạn.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000023', '机の上に本とペンがあります。', 'Trên bàn có sách và bút.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000024', '〜から〜まで', 'N5', 'particles', 'Từ ~ đến ~ (thời gian / địa điểm)', 'Mốc A + から + Mốc B + まで', 'Xác định điểm bắt đầu và điểm kết thúc của khoảng thời gian hoặc quãng đường.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000024', '授業は九時から十一時までです。', 'Tiết học từ 9 giờ đến 11 giờ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000024', 'うちから駅まで歩いて十分です。', 'Từ nhà đến ga đi bộ mất 10 phút.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000025', '〜や〜など', 'N5', 'particles', 'A, B và những thứ khác (liệt kê tiêu biểu)', 'Danh từ A + や + Danh từ B（+ など）', 'Liệt kê vài ví dụ tiêu biểu trong nhóm nhiều sự vật, hàm ý còn nhiều thứ khác nữa.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000025', 'かばんの中にノートや辞書などが入っています。', 'Trong cặp có vở, từ điển v.v.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000025', '休みはテニスや水泳をします。', 'Ngày nghỉ tôi chơi tennis, bơi lội...', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000026', '〜に〜がある', 'N5', 'existence', 'Có (đồ vật / sự kiện) ở ~', 'Địa điểm + に + Đồ vật / Sự việc + が + あります', 'Dùng động từ あります để nói về sự tồn tại của vật vô tri, cây cối hoặc sự kiện.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000026', '教室にテレビがあります。', 'Trong lớp học có ti vi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000026', '明日、会議があります。', 'Ngày mai có cuộc họp.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000027', '〜に〜がいる', 'N5', 'existence', 'Có (người / động vật) ở ~', 'Địa điểm + に + Người / Động vật + が + います', 'Dùng động từ います để diễn tả người hoặc động vật đang có mặt tại nơi nào đó.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000027', '庭に猫がいます。', 'Ở ngoài sân có con mèo.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000027', '事務所に誰もいません。', 'Trong văn phòng không có ai cả.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000028', '〜ます・〜ません', 'N5', 'tense_negation', 'Thể lịch sự hiện tại & phủ định', 'Động từ gốc ます + ます（khẳng định）/ ません（phủ định）', 'Diễn tả thói quen hàng ngày hoặc dự định trong tương lai ở sắc thái lịch sự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000028', '毎朝七時に朝ご飯を食べます。', 'Mỗi sáng tôi ăn sáng lúc 7 giờ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000028', 'お酒は飲みません。', 'Tôi không uống rượu.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000029', '〜ました・〜ませんでした', 'N5', 'tense_negation', 'Thể lịch sự quá khứ & phủ định quá khứ', 'Động từ gốc ます + ました / ませんでした', 'Diễn tả hành động đã hoàn thành hoặc không xảy ra trong quá khứ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000029', '昨日、図書館で勉強しました。', 'Hôm qua tôi đã học ở thư viện.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000029', '今朝、テレビを見ませんでした。', 'Sáng nay tôi đã không xem ti vi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000030', '〜ていない', 'N5', 'tense_negation', 'Chưa làm ~ / trạng thái chưa diễn ra', 'Động từ thể て + いない（います・いません）', 'Khi đi với まだ (vẫn chưa), diễn tả việc tính đến hiện tại vẫn chưa xảy ra hoặc chưa xong.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000030', 'まだ昼ご飯を食べていません。', 'Tôi vẫn chưa ăn trưa.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000030', '田中さんはまだ来ていないようです。', 'Anh Tanaka hình như vẫn chưa đến.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000031', '〜た・〜なかった', 'N5', 'tense_negation', 'Thể thông thường quá khứ', 'Động từ thể た / Động từ thể ない bỏ い + かった', 'Dùng khi nói chuyện thân mật hoặc trước danh từ/liên từ nối câu trong quá khứ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000031', '昨日、友達と会った。', 'Hôm qua tôi đã gặp bạn.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000031', '朝ご飯は食べなかった。', 'Tôi đã không ăn sáng.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000032', 'い形容詞（〜い・〜くない）', 'N5', 'adjectives', 'Tính từ đuôi い khẳng định & phủ định', 'Gốc tính từ い + い（khẳng định）/ + くない（phủ định）', 'Biểu thị tính chất sự vật; lưu ý ngoại lệ いい chia phủ định thành よくない.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000032', 'この部屋は広いです。', 'Căn phòng này rộng.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000032', '今日のテストは難しくないです。', 'Bài kiểm tra hôm nay không khó.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000033', 'な形容詞（〜だ・〜ではない）', 'N5', 'adjectives', 'Tính từ đuôi な (bổ nghĩa & vị ngữ)', 'Vị ngữ: Tính từ な + です / ではありません; Bổ nghĩa: Tính từ な + な + Danh từ', 'Mô tả tính chất; khi đứng trước danh từ phải giữ chữ な.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000033', '京都は静かな町です。', 'Kyoto là một thành phố yên tĩnh.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000033', 'この駅はあまり賑やかではありません。', 'Nhà ga này không náo nhiệt lắm.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000034', '〜くなる・〜になる', 'N5', 'adjectives', 'Trở nên / biến đổi trạng thái', 'Tính từ い bỏ い + くなる / Tính từ な・Danh từ + になる', 'Diễn tả sự thay đổi tự nhiên hoặc kết quả theo thời gian.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000034', 'だんだん暖かくなりました。', 'Trời dần trở nên ấm áp.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000034', '妹は来年二十歳になります。', 'Năm sau em gái tôi sẽ bước sang tuổi 20.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000035', '〜くて・〜で', 'N5', 'adjectives', 'Nối hai tính từ / danh từ mang nghĩa liệt kê', 'Tính từ い bỏ い + くて / Tính từ な・Danh từ + で', 'Nối các đặc điểm cùng chiều hoặc trung tính trong một câu mô tả.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000035', 'この店は安くておいしいです。', 'Quán này vừa rẻ vừa ngon.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000035', 'ミラーさんは親切でハンサムです。', 'Anh Miller vừa tốt bụng vừa đẹp trai.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000036', '〜が好きだ・〜が上手だ', 'N5', 'adjectives', 'Thích / giỏi / ghét / kém ~ (với trợ từ が)', 'Danh từ + が + 好き・嫌い・上手・下手 + です', 'Đối tượng của cảm xúc, sở thích và năng lực đi với trợ từ が chứ không dùng を.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000036', '私は日本料理が好きです。', 'Tôi thích món ăn Nhật.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000036', '山本さんは歌が上手ですね。', 'Bạn Yamamoto hát hay quá nhỉ.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000037', '〜てください', 'N5', 'request_suggestion', 'Xin hãy làm ~ (yêu cầu lịch sự)', 'Động từ thể て + ください', 'Dùng để nhờ vả, hướng dẫn hoặc mời ai đó làm việc gì một cách lịch sự.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000037', 'ここに名前を書いてください。', 'Xin hãy viết tên vào đây.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000037', 'すみませんが、ちょっと待ってください。', 'Xin lỗi, vui lòng đợi một chút.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000038', '〜ないでください', 'N5', 'request_suggestion', 'Xin đừng làm ~ (nhắc nhở lịch sự)', 'Động từ thể ない + で + ください', 'Yêu cầu hoặc khuyên người khác đừng thực hiện một hành động nào đó.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000038', 'ここで写真を撮らないでください。', 'Xin đừng chụp ảnh ở đây.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000038', '大切なことですから、忘れないでください。', 'Vì là việc quan trọng nên đừng quên nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000039', '〜ませんか', 'N5', 'request_suggestion', 'Cùng làm ~ không? (mời rủ lịch sự)', 'Động từ gốc ます + ませんか', 'Mời người nghe cùng tham gia hành động, tôn trọng lựa chọn từ chối của đối phương.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000039', 'いっしょに昼ご飯を食べませんか。', 'Chúng ta cùng ăn trưa nhé?', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000039', '土曜日、映画を見に行きませんか。', 'Thứ Bảy đi xem phim cùng không?', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000040', '〜ましょう', 'N5', 'request_suggestion', 'Hãy cùng làm ~ nhé (đề xuất hào hứng)', 'Động từ gốc ます + ましょう', 'Đưa ra đề nghị cùng làm ngay hoặc đáp lại đồng ý lời mời của người khác.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000040', 'そろそろ帰りましょう。', 'Chúng ta về thôi nào.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000040', 'ちょっと休みましょう。', 'Nghỉ một chút nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000041', '〜ましょうか', 'N5', 'request_suggestion', 'Để tôi làm giúp ~ nhé? / Chúng ta làm ~ nhé?', 'Động từ gốc ます + ましょうか', 'Đề nghị giúp đỡ người nghe một việc gì đó hoặc gợi ý cùng làm.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000041', '荷物を持ちましょうか。', 'Để tôi xách hành lý giúp bạn nhé?', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000041', '駅まで迎えに行きましょうか。', 'Tôi ra ga đón bạn nhé?', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000042', '〜たほうがいい', 'N5', 'request_suggestion', 'Nên làm / không nên làm ~', 'Động từ thể た / Động từ thể ない + ほうがいいです', 'Đưa ra lời khuyên trực tiếp cho người nghe nên hoặc không nên làm việc gì.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000042', '熱があるときは、早く寝たほうがいいです。', 'Khi bị sốt thì bạn nên đi ngủ sớm.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000042', '夜は甘いものを食べないほうがいいです。', 'Buổi tối thì không nên ăn đồ ngọt.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000043', '〜から（理由）', 'N5', 'reason_contrast', 'Vì ~ nên ~ (nêu lý do chủ quan)', 'Mệnh đề lý do + から、Mệnh đề kết quả', 'Trình bày nguyên nhân rồi dẫn tới kết luận, phán đoán hoặc yêu cầu của người nói.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000043', '時間がありませんから、急ぎましょう。', 'Vì không có thời gian nên hãy nhanh lên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000043', '今日は寒いから、コートを着ます。', 'Hôm nay lạnh nên tôi mặc áo khoác.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000044', '〜が・〜けれども', 'N5', 'reason_contrast', 'Nhưng mà ~ (nối hai ý tương phản nhẹ)', 'Mệnh đề A + が / けれども、Mệnh đề B', 'Nối hai mệnh đề trái ngược hoặc dùng để mở đầu nhẹ nhàng khi nhờ vả.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000044', '日本の生活は楽しいですが、少し寂しいです。', 'Cuộc sống ở Nhật vui nhưng hơi cô đơn một chút.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000044', 'すみませんが、塩を取ってください。', 'Xin lỗi, vui lòng lấy giúp tôi lọ muối.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000045', '〜て・〜で（順接）', 'N5', 'reason_contrast', 'Làm A rồi làm B (liệt kê hành động nối tiếp)', 'Động từ 1 thể て + Động từ 2 thể て + Động từ chính', 'Sắp xếp nhiều hành động theo trình tự thời gian liên tiếp trong một câu.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000045', '朝起きて、顔を洗って、学校へ行きます。', 'Sáng dậy, rửa mặt rồi tôi đi học.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000045', 'デパートへ行って、買い物をしました。', 'Tôi đã đến trung tâm thương mại và mua sắm.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000046', '〜の中で〜がいちばん', 'N5', 'comparison', 'Trong số ~ thì ~ nhất', 'Phạm vi + の中で + Đối tượng + がいちばん + Tính từ', 'So sánh bậc nhất trong một tập hợp cùng loại (mùa, món ăn, môn thể thao...).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000046', '季節の中で春がいちばん好きです。', 'Trong các mùa, tôi thích mùa xuân nhất.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000046', '日本料理の中で寿司がいちばんおいしいと思います。', 'Trong đồ ăn Nhật tôi nghĩ sushi ngon nhất.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000047', '〜がほしい', 'N5', 'desire', 'Muốn có (một đồ vật / điều gì)', 'Danh từ + が + ほしいです（ngôi thứ nhất）', 'Bày tỏ mong muốn sở hữu một đồ vật hay trạng thái cụ thể; khác 〜たい đi với động từ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000047', '新しいパソコンがほしいです。', 'Tôi muốn có một chiếc máy tính mới.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000047', '今、いちばんほしいものは時間です。', 'Thứ tôi muốn nhất bây giờ là thời gian.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000048', '〜の（名詞化）', 'N5', 'quoting_noun', 'Danh từ hóa động từ / tính từ', 'Động từ thể thông thường + の + が好き・上手・下手・速い...', 'Biến cụm động từ thành cụm danh từ để làm chủ ngữ hoặc tân ngữ cho câu.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000048', '絵を描くのが好きです。', 'Tôi thích vẽ tranh.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000048', '朝早く起きるのは大変です。', 'Việc dậy sớm vào buổi sáng thật vất vả.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000049', '〜に行く・来る', 'N5', 'quoting_noun', 'Đi / đến để làm việc gì (mục đích)', 'Địa điểm + へ + (Động từ gốc ます / Danh từ) + に + 行きます・来ます', 'Nêu mục đích của hành động di chuyển.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000049', 'デパートへ靴を買いに行きます。', 'Tôi đi trung tâm thương mại để mua giày.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000049', '日本へ経済の勉強に来ました。', 'Tôi đến Nhật để học kinh tế.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000050', '〜あげる・〜もらう・〜くれる', 'N5', 'giving_receiving', 'Tặng, nhận và được người khác tặng', 'A は B に V(vật) を あげる / もらう / くれる', 'あげます (tặng cho ai), もらいます (nhận từ ai), くれます (ai đó tặng cho mình/nhóm mình).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000050', '私は母に花をあげました。', 'Tôi đã tặng hoa cho mẹ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000050', '友だちが私に誕生日プレゼントをくれました。', 'Bạn tôi đã tặng quà sinh nhật cho tôi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000051', '〜まえに', 'N5', 'sequence', 'Trước khi làm việc gì', 'Động từ thể từ điển / Danh từ + の + まえに', 'Cho biết hành động ở vế sau diễn ra trước thời điểm hoặc hành động A; lưu ý động từ trước まえに luôn ở thể từ điển.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000051', '寝るまえに、歯を磨きます。', 'Trước khi đi ngủ tôi đánh răng.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000051', '食事のまえに、手を洗いましょう。', 'Trước bữa ăn hãy rửa tay nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000052', '可能形（〜られる・〜える）', 'N4', 'ability', 'Động từ thể khả năng (có thể làm)', 'Nhóm I: u -> eru; Nhóm II: ru -> rareru; する -> できる; くる -> こられる', 'Diễn tả năng lực hoặc điều kiện cho phép thực hiện hành động; đối tượng thường dùng trợ từ が.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000052', '私は漢字が少し読めます。', 'Tôi có thể đọc được một ít chữ Hán.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000052', 'この川では泳げません。', 'Không thể bơi ở con sông này.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000053', '〜てある', 'N4', 'aspect', 'Được làm sẵn (trạng thái kết quả có chủ đích)', 'N + が + Tha động từ thể て + ある', 'Miêu tả trạng thái tồn tại hiện tại do ai đó đã chủ ý thực hiện hành động từ trước; trợ từ trước động từ chuyển sang が.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000053', '壁に地図が貼ってあります。', 'Trên tường có dán sẵn bản đồ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000053', 'テーブルの上にお皿が並べてあります。', 'Trên bàn đã bày sẵn đĩa rồi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000054', '〜ておく', 'N4', 'aspect', 'Làm sẵn trước để chuẩn bị', 'Động từ thể て + おく（văn nói rút gọn thành とく）', 'Thực hiện một hành động trước để chuẩn bị cho việc sắp diễn ra hoặc giữ nguyên trạng thái.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000054', '旅行の前に切符を買っておきます。', 'Trước chuyến du lịch tôi mua sẵn vé.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000054', '会議の前に資料を配っておいてください。', 'Trước cuộc họp hãy phát sẵn tài liệu nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000055', '〜てしまう', 'N4', 'aspect', 'Làm xong hoàn toàn / lỡ làm (tiếc nuối)', 'Động từ thể て + しまう（rút gọn: ちゃう・じゃう）', 'Hai sắc thái chính: hoàn thành triệt để một việc gì, hoặc lỡ làm việc không mong muốn gây hối tiếc.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000055', '借りた本を全部読んでしまいました。', 'Tôi đã đọc xong hết cuốn sách mượn rồi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000055', '電車の中に傘を忘れてしまいました。', 'Tôi lỡ quên mất chiếc ô trên tàu điện rồi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000056', '〜てくる・〜ていく', 'N4', 'aspect', 'Tiến triển đến hiện tại / tiếp diễn về tương lai', 'Động từ thể て + くる / いく', '〜てくる: thay đổi hoặc hành động hướng gần tới hiện tại/người nói; 〜ていく: biến đổi dần về tương lai hoặc rời xa dần.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000056', '最近、日本語がだんだんわかってきました。', 'Gần đây tôi dần dần hiểu tiếng Nhật hơn rồi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000056', 'これからも日本語を勉強していきます。', 'Từ giờ trở đi tôi vẫn sẽ tiếp tục học tiếng Nhật.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000057', '〜はじめる・〜おわる', 'N4', 'aspect', 'Bắt đầu làm ~ / làm xong ~', 'Động từ gốc ます + はじめる / おわる', 'Nêu điểm khởi đầu hoặc kết thúc hoàn toàn của một hành động kéo dài.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000057', '急に雨が降りはじめました。', 'Trời đột nhiên bắt đầu đổ mưa.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000057', 'この小説をやっと読みおわりました。', 'Cuối cùng tôi cũng đọc xong cuốn tiểu thuyết này.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000058', '〜つづける', 'N4', 'aspect', 'Tiếp tục làm việc gì liên tục', 'Động từ gốc ます + つづける', 'Nhấn mạnh một hành động được duy trì đều đặn qua khoảng thời gian hoặc diễn ra không ngắt quãng.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000058', '三時間ずっと歩きつづけました。', 'Tôi đã đi bộ liên tục suốt 3 tiếng.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000058', 'あきらめないで努力しつづけたいです。', 'Tôi muốn không bỏ cuộc mà tiếp tục nỗ lực.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000059', '〜たばかり', 'N4', 'tense_negation', 'Vừa mới làm xong ~ (theo cảm nhận còn mới)', 'Động từ thể た + ばかりだ', 'Nhấn mạnh cảm nhận chủ quan của người nói rằng sự việc mới diễn ra chưa lâu (có thể vài giờ hoặc vài tháng).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000059', '先月日本へ来たばかりです。', 'Tôi mới vừa đến Nhật tháng trước thôi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000059', 'さっき昼ご飯を食べたばかりなので、おなかがいっぱいです。', 'Vì vừa mới ăn trưa lúc nãy nên bụng vẫn no.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000060', '〜ところだ', 'N4', 'tense_negation', 'Sắp / đang đúng lúc / vừa mới ~', 'Vる + ところ (sắp) / Vている + ところ (đang) / Vた + ところ (vừa mới)', 'Chỉ thời điểm tức thì của hành động xét theo khoảnh khắc đang nói.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000060', '今から昼ご飯を食べるところです。', 'Bây giờ tôi chuẩn bị ăn trưa đây.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000060', 'ちょうど今、駅に着いたところです。', 'Tôi vừa mới tới ga đúng lúc này.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000061', '〜ないで', 'N4', 'tense_negation', 'Làm B mà không làm A', 'Động từ thể ない + で + Động từ chính', 'Diễn tả trạng thái làm hành động thứ hai trong khi bỏ qua hành động thứ nhất vốn thường đi kèm.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000061', '今日は傘を持たないで出かけました。', 'Hôm nay tôi ra ngoài mà không mang ô.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000061', '辞書を使わないで新聞を読みます。', 'Tôi đọc báo mà không dùng từ điển.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000062', '〜ずに', 'N4', 'tense_negation', 'Không làm A mà làm B (hơi trang trọng)', 'Động từ thể ない bỏ ない + ずに (する -> せずに)', 'Ý nghĩa tương tự 〜ないで nhưng mang sắc thái văn viết hoặc trang trọng hơn.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000062', '昨日、晩ご飯を食べずに寝てしまいました。', 'Hôm qua tôi đã ngủ luôn mà không ăn tối.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000062', '誰にも相談せずに決めました。', 'Tôi đã quyết định mà không bàn với ai.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000063', '〜と（条件）', 'N4', 'condition', 'Hễ A thì tất yếu xảy ra B', 'Thể từ điển / Thể ない + と、Mệnh đề kết quả', 'Quy luật tự nhiên, thao tác máy móc, chỉ đường; vế sau không dùng câu mệnh lệnh, ý chí hay nhờ vả.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000063', 'このボタンを押すと、おつりが出ます。', 'Ấn nút này thì tiền thối sẽ ra.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000063', '春になると、桜が咲きます。', 'Hễ sang xuân là hoa anh đào nở.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000064', '〜たら', 'N4', 'condition', 'Nếu ~ / Sau khi ~ thì ~', 'Thể quá khứ thông thường (〜た・〜かった・〜だった) + ら', 'Dùng rất linh hoạt cho giả định, tình huống tương lai chắc chắn xảy ra, hoặc sau khi hoàn thành A; vế sau có thể là ý định, mời gọi.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000064', '雨が降ったら、試合は中止です。', 'Nếu trời mưa thì trận đấu sẽ bị hủy.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000064', '家へ帰ったら、すぐ電話をください。', 'Về đến nhà rồi hãy gọi cho tôi ngay nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000065', '〜ば', 'N4', 'condition', 'Nếu / Miễn là A thì B', 'Nhóm I: u -> eba; Nhóm II: ru -> reba; Tính từ い -> ければ; ない -> なければ', 'Nhấn mạnh điều kiện cần để kết quả ở vế sau xảy ra hoặc đưa ra giả định chung.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000065', '毎日練習すれば、上手になります。', 'Nếu luyện tập mỗi ngày thì sẽ giỏi lên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000065', '天気がよければ、散歩しましょう。', 'Nếu thời tiết đẹp thì đi dạo nhé.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000066', '〜なら', 'N4', 'condition', 'Nếu là nói về ~ (dựa vào thông tin vừa nghe)', 'Danh từ / Tính từ な / Động từ thông thường + なら', 'Đón lấy chủ đề hoặc lời đối phương vừa nói để đưa ra lời khuyên hay nhận xét phù hợp.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000066', '京都へ行くなら、秋がいちばんきれいですよ。', 'Nếu đi Kyoto thì mùa thu là đẹp nhất đấy.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000066', 'カメラなら、駅前の店が安いです。', 'Nếu nói về máy ảnh thì cửa hàng trước ga rẻ lắm.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000067', '〜たらどうですか', 'N4', 'condition', 'Bạn thử làm ~ xem sao? (gợi ý nhẹ nhàng)', 'Động từ thể た + らどうですか', 'Khuyên hoặc gợi ý cho người nghe một giải pháp để cân nhắc.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000067', '頭が痛いなら、少し休んだらどうですか。', 'Nếu đau đầu thì bạn thử nghỉ một chút xem sao?', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000067', '先生に聞いてみたらどうですか。', 'Sao bạn không thử hỏi thầy xem?', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000068', '〜ので', 'N4', 'reason_contrast', 'Vì ~ nên ~ (lý do khách quan, lịch sự)', 'Thể thông thường + ので (Tính từ な・Danh từ giữ な + ので)', 'Giải thích nguyên nhân một cách khách quan, mềm mại hơn から, hay dùng khi xin phép hoặc xin lỗi.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000068', 'バスが遅れたので、授業に間に合いませんでした。', 'Vì xe buýt đến trễ nên tôi không kịp giờ học.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000068', 'ここは静かなので、勉強しやすいです。', 'Vì ở đây yên tĩnh nên rất dễ học.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000069', '〜のに', 'N4', 'reason_contrast', 'Thế mà / Mặc dù ~ nhưng lại ~ (trái kỳ vọng)', 'Thể thông thường + のに (Tính từ な・Danh từ giữ な + のに)', 'Bày tỏ sự bất ngờ, thất vọng hoặc không hài lòng vì kết quả trái ngược hẳn với điều kiện ban đầu.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000069', '目覚まし時計をかけたのに、寝坊してしまいました。', 'Đã đặt đồng hồ báo thức rồi vậy mà vẫn ngủ quên mất.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000069', '日曜日なのに、仕事に行かなければなりません。', 'Dù là Chủ nhật mà vẫn phải đi làm.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000070', '〜ても', 'N4', 'reason_contrast', 'Cho dù ~ đi nữa thì vẫn ~', 'Động từ thể て + も / Tính từ い bỏ い + くても / Tính từ な・Danh từ + でも', 'Nêu giả định điều kiện dù có xảy ra thì kết quả vẫn không đổi.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000070', '雨が降っても、サッカーの試合をします。', 'Cho dù trời có mưa thì vẫn thi đấu bóng đá.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000070', 'いくら高くても、この本を買いたいです。', 'Dù có đắt thế nào tôi vẫn muốn mua cuốn sách này.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000071', '〜し、〜し', 'N4', 'reason_contrast', 'Vừa ~ vừa ~ / Hơn nữa lại ~', 'Thể thông thường + し、Thể thông thường + し', 'Liệt kê nhiều đặc điểm đồng hướng hoặc nhiều lý do cộng dồn để giải thích cho kết luận.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000071', 'この町は交通も便利だし、物価も安いです。', 'Thành phố này giao thông vừa tiện, vật giá lại rẻ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000071', '今日は忙しいし、天気も悪いし、家にいよう。', 'Hôm nay vừa bận vừa thời tiết xấu nên ở nhà thôi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000072', '〜て（原因・理由）', 'N4', 'reason_contrast', 'Vì ~ mà (cảm xúc / kết quả không chủ ý)', 'Động từ thể て / Tính từ い bỏ い + くて / Tính từ な + で', 'Chỉ nguyên nhân nhẹ dẫn đến cảm xúc (vui, buồn, lo) hoặc tình huống ngoài ý muốn ở vế sau.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000072', 'ニュースを聞いて、びっくりしました。', 'Nghe tin tức mà tôi giật cả mình.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000072', '道が込んでいて、遅れてしまいました。', 'Vì đường kẹt nên tôi bị trễ mất.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000073', '〜すぎる', 'N4', 'adjectives', 'Quá mức / vượt quá giới hạn', 'Động từ gốc ます / Tính từ い bỏ い / Tính từ な + すぎる', 'Nhận xét hành động hay tính chất vượt quá mức bình thường, thường mang sắc thái không tốt.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000073', '昨日、お酒を飲みすぎてしまいました。', 'Hôm qua tôi đã uống quá nhiều rượu.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000073', 'このセーターは私には大きすぎます。', 'Chiếc áo len này quá rộng so với tôi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000074', '〜やすい・〜にくい', 'N4', 'adjectives', 'Dễ làm ~ / Khó làm ~', 'Động từ gốc ます + やすい（dễ）/ にくい（khó）', 'Đánh giá tính chất khách quan của sự vật rằng nó thuận tiện hay gây khó khăn khi thực hiện.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000074', 'このペンはとても書きやすいです。', 'Cây bút này rất dễ viết.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000074', 'この漢字は画数が多くて覚えにくいです。', 'Chữ Hán này nhiều nét nên khó nhớ.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000075', '〜そうだ（様態）', 'N4', 'adjectives', 'Trông có vẻ như ~ / Sắp sửa ~', 'Động từ gốc ます / Tính từ い bỏ い / Tính từ な + そうだ', 'Suy đoán bằng trực giác dựa trên vẻ ngoài quan sát được ngay lúc nói (lưu ý: いい -> よさそうだ, ない -> なさそうだ).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000075', 'このケーキはとてもおいしそうですね。', 'Chiếc bánh này trông ngon quá nhỉ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000075', '今にも雨が降りそうです。', 'Trời trông cứ như sắp mưa đến nơi rồi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000076', '〜がる', 'N4', 'adjectives', 'Có vẻ muốn / tỏ ra cảm thấy ~ (ngôi thứ 3)', 'Tính từ cảm xúc bỏ い / な + がる（thường chia がっている）', 'Miêu tả cảm giác, mong muốn của người khác qua biểu hiện bên ngoài (chủ ngữ không phải người nói).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000076', '子供は新しいおもちゃをほしがっています。', 'Đứa trẻ có vẻ rất muốn món đồ chơi mới.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000076', '妹は暗いところを怖がっています。', 'Em gái tôi sợ chỗ tối.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000077', '〜てみる', 'N4', 'request_suggestion', 'Làm thử xem sao', 'Động từ thể て + みる', 'Thử trải nghiệm một việc gì đó để kiểm tra hoặc biết cảm giác/kết quả ra sao.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000077', '日本の納豆を食べてみたいです。', 'Tôi muốn ăn thử món natto của Nhật.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000077', 'サイズが合うか、一度着てみてください。', 'Hãy mặc thử một lần xem có vừa cỡ không.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000078', '〜なさい', 'N4', 'request_suggestion', 'Hãy làm ~ (mệnh lệnh nhẹ nhàng)', 'Động từ gốc ます + なさい', 'Thường dùng từ người lớn nói với trẻ nhỏ, thầy cô với học sinh hoặc trong đề thi.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000078', '早く寝なさい。明日は学校ですよ。', 'Đi ngủ sớm đi con. Ngày mai đi học đấy.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000078', '次の文を読んで質問に答えなさい。', 'Hãy đọc đoạn văn sau và trả lời câu hỏi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000079', '〜てほしい', 'N4', 'request_suggestion', 'Muốn ai đó làm gì cho mình', 'Người + に + Động từ thể て + ほしい', 'Bày tỏ mong muốn người khác thực hiện hành động nào đó.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000079', '友達に手伝ってほしいです。', 'Tôi muốn bạn giúp đỡ mình.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000079', 'みんなに私の国へ来てほしいです。', 'Tôi muốn mọi người đến thăm đất nước tôi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000080', '〜ようと思う', 'N4', 'intention', 'Tôi định sẽ làm ~ (dự định đang hình thành)', 'Động từ thể ý chí (〜よう / 〜おう) + と思う（と思っている）', 'Nêu ý định của người nói vừa nảy ra hoặc dự định mang tính cá nhân linh hoạt hơn つもり.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000080', '夏休みに国へ帰ろうと思っています。', 'Tôi đang định nghỉ hè sẽ về quê hương.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000080', '来月から水泳を始めようと思います。', 'Tôi định từ tháng sau sẽ bắt đầu học bơi.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000081', '〜予定だ', 'N4', 'intention', 'Dự kiến / theo lịch trình sẽ ~', 'Động từ thể từ điển / Danh từ + の + 予定だ', 'Thông báo một kế hoạch, lịch trình đã được sắp xếp sẵn (thường mang tính lịch hẹn hoặc công việc).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000081', '来月の十日に出張する予定です。', 'Theo lịch tôi sẽ đi công tác vào ngày 10 tháng sau.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000081', '会議は二時間の予定です。', 'Cuộc họp dự kiến kéo dài hai tiếng.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000082', '〜ことにする・〜ことになる', 'N4', 'intention', 'Tự quyết định / được quyết định rằng', 'Vる・Vない + ことにする（chủ động）/ + ことになる（khách quan）', 'ことにする: bản thân tự quyết định; ことになる: tổ chức/hoàn cảnh quyết định không phụ thuộc ý muốn cá nhân.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000082', '健康のために、毎日歩くことにしました。', 'Vì sức khỏe, tôi đã quyết định mỗi ngày sẽ đi bộ.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000082', '来月、大阪へ転勤することになりました。', 'Tháng sau tôi được điều chuyển công tác tới Osaka.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000083', '〜と思う', 'N4', 'quoting_noun', 'Tôi nghĩ rằng ~ (trích dẫn suy nghĩ)', 'Thể thông thường + と思う', 'Trình bày ý kiến, suy đoán của bản thân; khi hỏi ý kiến người khác dùng と思いますか.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000083', '明日は雨が降ると思います。', 'Tôi nghĩ ngày mai trời sẽ mưa.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000083', '日本の生活はどう思いますか。', 'Bạn nghĩ sao về cuộc sống ở Nhật?', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000084', '〜と言う', 'N4', 'quoting_noun', 'Nói rằng ~ (tường thuật lời nói)', 'Thể thông thường / 「Câu trực tiếp」 + と言う', 'Thuật lại lời nói gián tiếp hoặc trích nguyên văn lời ai đó đã nói.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000084', '先生は明日テストがあると言いました。', 'Thầy giáo nói rằng ngày mai có bài kiểm tra.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000084', '田中さんは「ちょっと遅れます」と言っていました。', 'Anh Tanaka nói là ''Tôi sẽ đến muộn một chút''.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000085', '〜かどうか', 'N4', 'quoting_noun', 'Liệu có ~ hay không', 'Thể thông thường + かどうか', 'Lồng ghép một câu hỏi Có/Không vào làm tân ngữ cho động từ biết, nhớ, hỏi, kiểm tra...') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000085', '明日、彼が来るかどうかわかりません。', 'Tôi không biết ngày mai anh ấy có đến hay không.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000085', 'この料理が辛いかどうか食べてみます。', 'Tôi ăn thử xem món này có cay hay không.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000086', '〜ために', 'N4', 'quoting_noun', 'Để ~ (mục đích) / Vì ~ (nguyên nhân)', 'Động từ thể từ điển / Danh từ + の + ために', 'Trước động từ ý chí chỉ mục đích cần cố gắng đạt được; hoặc nêu nguyên nhân gây tác động ở danh từ.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000086', '自分の店を持つために、お金をためています。', 'Tôi đang tiết kiệm tiền để có cửa hàng riêng.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000086', '台風のために電車が止まりました。', 'Vì bão nên tàu điện đã dừng chạy.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000087', '〜ように', 'N4', 'quoting_noun', 'Để có thể đạt tới trạng thái ~', 'Động từ khả năng / Động từ thể ない / Tự động từ + ように', 'Khác với ために, dùng với động từ không mang ý chí trực tiếp (có thể làm, trở nên, không bị quên) để nêu mục tiêu.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000087', '忘れないようにメモします。', 'Tôi ghi chú lại để không bị quên.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000087', '早く日本語が話せるように毎日練習します。', 'Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật sớm.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000088', '〜てあげる・〜てもらう・〜てくれる', 'N4', 'giving_receiving', 'Làm giúp / nhờ làm / được ai làm cho', 'Động từ thể て + あげる / もらう / くれる', 'Diễn tả ân huệ hành động giữa người thực hiện và người nhận lợi ích.') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000088', '私は友達に漢字の読み方を教えてあげました。', 'Tôi đã dạy bạn cách đọc chữ Hán.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000088', '先輩にパソコンを直してもらいました。', 'Tôi đã nhờ anh khóa trên sửa máy tính giúp.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000089', '受身形（〜られる・〜れる）', 'N4', 'voice_politeness', 'Thể bị động (bị / được ai làm gì)', 'Nhóm I: u -> areru; Nhóm II: ru -> rareru; する -> される; くる -> こられる', 'Người hoặc vật chịu tác động từ hành động của người khác (thường dùng với に trước tác nhân).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000089', '私は先生にほめられました。', 'Tôi đã được thầy giáo khen.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000089', '電車の中で隣の人に足を踏まれました。', 'Trên tàu tôi bị người bên cạnh giẫm lên chân.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_points (id, pattern, level, category, meaning_vi, formula, usage_vi) values ('10000000-0000-0000-0000-000000000090', '〜かもしれない', 'N4', 'voice_politeness', 'Có lẽ / biết đâu chừng ~', 'Thể thông thường + かもしれない (Danh từ・Tính từ な không thêm だ)', 'Nêu phán đoán với xác suất chưa chắc chắn (khoảng 50%).') on conflict (id) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000090', '午後から雪が降るかもしれません。', 'Từ chiều trở đi có lẽ tuyết sẽ rơi.', 0) on conflict (grammar_id, sort_order) do nothing;
insert into public.grammar_examples (grammar_id, sentence_ja, translation_vi, sort_order) values ('10000000-0000-0000-0000-000000000090', '彼はもう帰ったかもしれません。', 'Có khi anh ấy đã về rồi cũng nên.', 1) on conflict (grammar_id, sort_order) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 日本へ行ったことがあります。', '["Tôi đã từng đến Nhật Bản.", "Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 0, null, 'trim_only', 'Diễn tả trải nghiệm đã xảy ra trước thời điểm nói.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 1, 'cloze', '日本へ（　）ことがあります。', null, null, '["行った"]'::jsonb, 'trim_only', 'Trước ことがある dùng động từ thể た.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000002', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 日本語を勉強したいです。', '["Một câu hỏi về tên người.", "Tôi muốn học tiếng Nhật.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 1, null, 'trim_only', 'Diễn tả mong muốn thực hiện một hành động của người nói.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000002', 1, 'cloze', '日本語を勉強（　）です。', null, null, '["したい"]'::jsonb, 'trim_only', '勉強します bỏ ます rồi thêm たい thành 勉強したい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000003', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 本を読んでいます。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Tôi đang đọc sách.", "Một lời chào khi gặp mặt."]'::jsonb, 2, null, 'trim_only', 'Trong ví dụ này, diễn tả một hành động đang diễn ra.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000003', 1, 'cloze', '今、本を（　）います。', null, null, '["読んで"]'::jsonb, 'trim_only', '読む đổi sang thể て là 読んで; tiếp theo là います.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000004', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: ここで写真を撮ってもいいですか。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt.", "Tôi có thể chụp ảnh ở đây không?"]'::jsonb, 3, null, 'trim_only', 'Hỏi hoặc cho phép một hành động; ví dụ dùng câu hỏi lịch sự.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000004', 1, 'cloze', 'ここで写真を（　）もいいですか。', null, null, '["撮って"]'::jsonb, 'trim_only', '撮る đổi sang thể て là 撮って.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000005', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: ここでタバコを吸ってはいけません。', '["Không được hút thuốc ở đây.", "Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 0, null, 'trim_only', 'Nêu điều cấm; cách nói có thể mạnh tùy quan hệ và tình huống.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000010', '10000000-0000-0000-0000-000000000005', 1, 'cloze', 'ここでタバコを（　）はいけません。', null, null, '["吸って"]'::jsonb, 'trim_only', '吸う đổi sang thể て là 吸って.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000011', '10000000-0000-0000-0000-000000000006', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 明日までに宿題をしなければなりません。', '["Một câu hỏi về tên người.", "Tôi phải làm bài tập trước hạn ngày mai.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 1, null, 'trim_only', 'Nêu nghĩa vụ; ví dụ しない chuyển thành しなければならない.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000012', '10000000-0000-0000-0000-000000000006', 1, 'cloze', '明日までに宿題をし（　）なりません。', null, null, '["なければ"]'::jsonb, 'trim_only', 'しない chuyển thành しなければなりません.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000007', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 今日は学校へ行かなくてもいいです。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Hôm nay không cần đến trường.", "Một lời chào khi gặp mặt."]'::jsonb, 2, null, 'trim_only', 'Diễn tả không bắt buộc làm, không phải lệnh cấm làm.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000014', '10000000-0000-0000-0000-000000000007', 1, 'cloze', '今日は学校へ（　）なくてもいいです。', null, null, '["行か"]'::jsonb, 'trim_only', '行かない bỏ い rồi thêm くてもいい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000015', '10000000-0000-0000-0000-000000000008', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 来年、日本へ行くつもりです。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt.", "Tôi dự định đến Nhật Bản vào năm sau."]'::jsonb, 3, null, 'trim_only', 'Diễn tả dự định của người nói; ví dụ dùng dạng lịch sự つもりです.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000016', '10000000-0000-0000-0000-000000000008', 1, 'cloze', '来年、日本へ行く（　）です。', null, null, '["つもり"]'::jsonb, 'trim_only', 'Thể từ điển 行く kết hợp つもりです để nêu dự định.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000017', '10000000-0000-0000-0000-000000000009', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 音楽を聞きながら勉強します。', '["Tôi vừa nghe nhạc vừa học.", "Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 0, null, 'trim_only', 'Hai hành động cùng chủ thể; mệnh đề sau là hành động chính trong ví dụ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000018', '10000000-0000-0000-0000-000000000009', 1, 'cloze', '音楽を（　）ながら勉強します。', null, null, '["聞き"]'::jsonb, 'trim_only', '聞きます bỏ ます, thêm ながら.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000019', '10000000-0000-0000-0000-000000000010', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: バスより電車のほうが速いです。', '["Một câu hỏi về tên người.", "So với xe buýt, tàu điện nhanh hơn.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt."]'::jsonb, 1, null, 'trim_only', 'So sánh hai đối tượng theo đặc điểm được nêu, không khái quát mọi mặt.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000020', '10000000-0000-0000-0000-000000000010', 1, 'cloze', 'バスより電車の（　）が速いです。', null, null, '["ほう"]'::jsonb, 'trim_only', 'Cấu trúc AよりBのほうが so sánh hai đối tượng.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000021', '10000000-0000-0000-0000-000000000011', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 私は日本語を話すことができます。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Tôi có thể nói tiếng Nhật.", "Một lời chào khi gặp mặt."]'::jsonb, 2, null, 'trim_only', 'Trong ví dụ, diễn tả năng lực thực hiện một hành động.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000022', '10000000-0000-0000-0000-000000000011', 1, 'cloze', '私は日本語を話すことが（　）。', null, null, '["できます"]'::jsonb, 'trim_only', '話すことができます diễn tả có thể nói.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000023', '10000000-0000-0000-0000-000000000012', 1, 'mcq', 'Chọn nghĩa phù hợp với câu: 手を洗ってから、ご飯を食べます。', '["Một câu hỏi về tên người.", "Một lời cảm ơn.", "Một lời chào khi gặp mặt.", "Tôi rửa tay rồi mới ăn cơm."]'::jsonb, 3, null, 'trim_only', 'Diễn tả thứ tự hành động A rồi B.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000024', '10000000-0000-0000-0000-000000000012', 1, 'cloze', '手を（　）から、ご飯を食べます。', null, null, '["洗って"]'::jsonb, 'trim_only', '洗う đổi thành 洗って, tiếp theo から nêu thứ tự.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000025', '10000000-0000-0000-0000-000000000013', 1, 'mcq', 'Điền trợ từ thích hợp: 私（　）大学生です。', '["は", "を", "に", "へ"]'::jsonb, 0, null, 'trim_only', 'Trợ từ は đánh dấu chủ đề của câu.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000026', '10000000-0000-0000-0000-000000000013', 1, 'cloze', '山田さんは会社員（　）。', null, null, '["です", "ます"]'::jsonb, 'trim_only', 'Danh từ kết hợp です ở cuối câu khẳng định lịch sự.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000027', '10000000-0000-0000-0000-000000000014', 1, 'mcq', 'Chọn dạng phủ định đúng: あの人は田中さん（　）。', '["ではありません", "ではありませんか", "くないです", "ます"]'::jsonb, 0, null, 'trim_only', 'Danh từ phủ định lịch sự dùng ではありません.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000028', '10000000-0000-0000-0000-000000000014', 1, 'cloze', '明日は休み（　）ありません。', null, null, '["では", "じゃ"]'::jsonb, 'trim_only', 'Cụm cố định ではありません dùng để phủ định danh từ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000029', '10000000-0000-0000-0000-000000000015', 1, 'mcq', 'Chọn trợ từ cuối câu để đặt câu hỏi: あなたは留学生です（　）。', '["よ", "か", "ね", "が"]'::jsonb, 1, null, 'trim_only', 'Trợ từ か ở cuối câu tạo câu nghi vấn lịch sự.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000030', '10000000-0000-0000-0000-000000000015', 1, 'cloze', 'これは誰の傘です（　）。', null, null, '["か"]'::jsonb, 'trim_only', 'Đặt か ở cuối câu để hỏi.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000031', '10000000-0000-0000-0000-000000000016', 1, 'mcq', 'Điền trợ từ nối hai danh từ: これは日本（　）車です。', '["を", "に", "の", "で"]'::jsonb, 2, null, 'trim_only', 'Trợ từ の nối hai danh từ để chỉ nguồn gốc/sở hữu.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000032', '10000000-0000-0000-0000-000000000016', 1, 'cloze', '兄（　）部屋は二階にあります。', null, null, '["の"]'::jsonb, 'trim_only', 'の biểu thị quan hệ sở hữu giữa 兄 và 部屋.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000033', '10000000-0000-0000-0000-000000000017', 1, 'mcq', 'Chọn trợ từ mang nghĩa ''cũng'': リンさんはベトナム人です。ナムさん（　）ベトナム人です。', '["は", "も", "を", "へ"]'::jsonb, 1, null, 'trim_only', 'Dùng も thay は khi khẳng định điều tương tự cho đối tượng tiếp theo.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000034', '10000000-0000-0000-0000-000000000017', 1, 'cloze', 'コーヒーを飲みます。紅茶（　）飲みます。', null, null, '["も"]'::jsonb, 'trim_only', 'も mang nghĩa ''cũng'' khi liệt kê thêm hành động giống nhau.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000035', '10000000-0000-0000-0000-000000000018', 1, 'mcq', 'Điền trợ từ chỉ tân ngữ: 図書館で本（　）読みます。', '["が", "で", "を", "と"]'::jsonb, 2, null, 'trim_only', 'Động từ đọc (読む) đi với tân ngữ qua trợ từ を.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000036', '10000000-0000-0000-0000-000000000018', 1, 'cloze', '毎晩、音楽（　）聞きます。', null, null, '["を"]'::jsonb, 'trim_only', 'を đánh dấu đối tượng trực tiếp của động từ 聞きます.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000037', '10000000-0000-0000-0000-000000000019', 1, 'mcq', 'Chọn câu dùng đúng trợ từ chỉ thời gian: 私は（　）寝ます。', '["毎日十一時に", "今日に十一時", "明日に", "毎晩に"]'::jsonb, 0, null, 'trim_only', 'Thời gian có con số cụ thể như 十一時 dùng に, còn 毎日 không đi kèm に.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000038', '10000000-0000-0000-0000-000000000019', 1, 'cloze', '日曜日の朝九時（　）友達に会います。', null, null, '["に"]'::jsonb, 'trim_only', 'Giờ cụ thể (九時) cần trợ từ に.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000039', '10000000-0000-0000-0000-000000000020', 1, 'mcq', 'Chọn trợ từ đi với động từ di chuyển: 夏休みに京都（　）行きます。', '["を", "で", "へ", "から"]'::jsonb, 2, null, 'trim_only', 'Với động từ đi/đến/về dùng へ hoặc に sau địa điểm.') on conflict (id) do nothing;
