insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000021', 1, 'mcq', 'Điền trợ từ chỉ nơi diễn ra hành động: スーパー（　）りんごを買います。', '["へ", "に", "を", "で"]'::jsonb, 3, null, 'trim_only', 'Nơi diễn ra hành động mua sắm dùng trợ từ で.') on conflict (id) do nothing;
