insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000043', '10000000-0000-0000-0000-000000000022', 1, 'mcq', 'Chọn trợ từ chỉ phương tiện: バス（　）空港まで行きました。', '["で", "に", "へ", "を"]'::jsonb, 0, null, 'trim_only', 'Phương tiện di chuyển dùng trợ từ で.') on conflict (id) do nothing;
