insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000045', '10000000-0000-0000-0000-000000000023', 1, 'mcq', 'Điền trợ từ nghĩa ''cùng với'': 週末に姉（　）買い物に行きます。', '["や", "と", "へ", "に"]'::jsonb, 1, null, 'trim_only', 'Thực hiện hành động cùng người khác dùng trợ từ と.') on conflict (id) do nothing;
