insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000053', '10000000-0000-0000-0000-000000000027', 1, 'mcq', 'Chọn động từ đúng cho người/động vật: 教室に新しい学生が（　）。', '["あります", "います", "です", "します"]'::jsonb, 1, null, 'trim_only', 'Người và động vật dùng います.') on conflict (id) do nothing;
