insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000055', '10000000-0000-0000-0000-000000000028', 1, 'mcq', 'Chọn dạng phủ định hiện tại lịch sự của 行く: 今夜は出掛け（　）。', '["ます", "ました", "ません", "ませんでした"]'::jsonb, 2, null, 'trim_only', 'Phủ định hiện tại lịch sự dùng đuôi ません.') on conflict (id) do nothing;
