insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000059', '10000000-0000-0000-0000-000000000030', 1, 'mcq', 'Chọn dạng diễn tả ''vẫn chưa làm'': まだレポートを（　）。', '["書いていません", "書きました", "書きます", "書きません"]'::jsonb, 0, null, 'trim_only', 'Với trạng từ まだ, dùng 〜ていません để chỉ việc chưa hoàn thành.') on conflict (id) do nothing;
