insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000063', '10000000-0000-0000-0000-000000000032', 1, 'mcq', 'Chọn phủ định đúng của いい: 今日は天気が（　）です。', '["いくない", "いいくない", "よくない", "よいない"]'::jsonb, 2, null, 'trim_only', 'いい là ngoại lệ, khi chia phủ định đổi gốc thành よくない.') on conflict (id) do nothing;
