insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000076', '10000000-0000-0000-0000-000000000038', 1, 'cloze', '夜遅くまで起き（　）ください。', null, null, '["ないで"]'::jsonb, 'trim_only', 'Phủ định thể ない trước でください.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000077', '10000000-0000-0000-0000-000000000039', 1, 'mcq', 'Chọn câu mời rủ lịch sự: 明日、いっしょにテニスを（　）。', '["しませんでした", "しませんか", "しています", "したかった"]'::jsonb, 1, null, 'trim_only', '〜ませんか là lời mời lịch sự ''cùng làm nhé?''.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000078', '10000000-0000-0000-0000-000000000039', 1, 'cloze', 'ちょっと喫茶店でコーヒーを飲み（　）か。', null, null, '["ません"]'::jsonb, 'trim_only', 'Cấu trúc mời gọi lịch sự Vません + か.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000079', '10000000-0000-0000-0000-000000000040', 1, 'mcq', 'Chọn câu đáp đồng ý phù hợp cho lời mời ''飲みませんか'': ええ、（　）。', '["飲みません", "飲みました", "飲みましょう", "飲んで"]'::jsonb, 2, null, 'trim_only', 'Đáp lại đồng thuận lời rủ thường dùng Vましょう.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000080', '10000000-0000-0000-0000-000000000040', 1, 'cloze', '授業が始まりますから、静かにし（　）。', null, null, '["ましょう"]'::jsonb, 'trim_only', 'Đề nghị mọi người cùng hành động dùng ましょう.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000081', '10000000-0000-0000-0000-000000000041', 1, 'mcq', 'Chọn câu đề nghị giúp đỡ: 雨が降ってきましたね。傘を（　）。', '["貸しましょう", "借りますか", "貸しません", "貸しましょうか"]'::jsonb, 3, null, 'trim_only', 'Vましょうか thể hiện ý ngỏ lời giúp đối phương.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000082', '10000000-0000-0000-0000-000000000041', 1, 'cloze', '暑いですから、窓を開け（　）か。', null, null, '["ましょう"]'::jsonb, 'trim_only', 'Ngỏ ý mở cửa sổ giúp đối phương: 開けましょうか.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000083', '10000000-0000-0000-0000-000000000042', 1, 'mcq', 'Chọn thể đúng để khuyên ''nên đi khám'': 薬を（　）ほうがいいですよ。', '["飲んだ", "飲む", "飲んで", "飲みます"]'::jsonb, 0, null, 'trim_only', 'Khuyên NÊN làm dùng Động từ thể た + ほうがいい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000084', '10000000-0000-0000-0000-000000000042', 1, 'cloze', '疲れているなら、今日は無理を（　）ほうがいいです。', null, null, '["しない"]'::jsonb, 'trim_only', 'Khuyên KHÔNG nên dùng thể ない + ほうがいい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000085', '10000000-0000-0000-0000-000000000043', 1, 'mcq', 'Chọn liên từ chỉ lý do phù hợp: 風邪をひいた（　）、今日は会社を休みます。', '["のでが", "から", "ても", "のに"]'::jsonb, 1, null, 'trim_only', 'から đặt sau mệnh đề nguyên nhân mang nghĩa ''vì''.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000086', '10000000-0000-0000-0000-000000000043', 1, 'cloze', '漢字が難しい（　）、毎日練習しています。', null, null, '["から"]'::jsonb, 'trim_only', 'Mệnh đề đầu giải thích lý do cho hành động sau.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000087', '10000000-0000-0000-0000-000000000044', 1, 'mcq', 'Điền từ nối tương phản: 部屋は狭い（　）、とてもきれいです。', '["から", "より", "が", "て"]'::jsonb, 2, null, 'trim_only', 'Hai tính chất trái chiều ''hẹp'' và ''đẹp'' nối bằng が / けれども.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000088', '10000000-0000-0000-0000-000000000044', 1, 'cloze', '日本語は難しいです（　）、おもしろいです。', null, null, '["が", "けれども"]'::jsonb, 'trim_only', 'Liên từ が hoặc けれども nối hai nhận xét tương phản.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000089', '10000000-0000-0000-0000-000000000045', 1, 'mcq', 'Chọn thể nối hai hành động liên tiếp: 電車に（　）、会社へ行きます。', '["乗る", "乗った", "乗ります", "乗って"]'::jsonb, 3, null, 'trim_only', 'Động từ 乗る nối tiếp sang hành động sau đổi sang thể て là 乗って.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000090', '10000000-0000-0000-0000-000000000045', 1, 'cloze', '家に帰っ（　）、すぐシャワーを浴びました。', null, null, '["て"]'::jsonb, 'trim_only', '帰る đổi sang thể て thành 帰って.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000091', '10000000-0000-0000-0000-000000000046', 1, 'mcq', 'Điền từ chỉ mức độ cao nhất: スポーツの中でサッカーが（　）おもしろいです。', '["いちばん", "もっと", "ほど", "ばかり"]'::jsonb, 0, null, 'trim_only', 'Mẫu so sánh nhất trong phạm vi 〜の中で dùng いちばん.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000092', '10000000-0000-0000-0000-000000000046', 1, 'cloze', '果物の中（　）りんごがいちばん好きです。', null, null, '["で"]'::jsonb, 'trim_only', 'Sau danh từ chỉ nhóm dùng の中で.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000093', '10000000-0000-0000-0000-000000000047', 1, 'mcq', 'Điền trợ từ đúng trước ほしい: 誕生日に時計（　）ほしいです。', '["を", "が", "に", "で"]'::jsonb, 1, null, 'trim_only', 'Đối tượng mong muốn đi với ほしい luôn dùng trợ từ が.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000094', '10000000-0000-0000-0000-000000000047', 1, 'cloze', '寒いから、暖かい飲み物が（　）です。', null, null, '["ほしい", "欲しい"]'::jsonb, 'trim_only', 'Muốn có đồ vật dùng tính từ ほしい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000095', '10000000-0000-0000-0000-000000000048', 1, 'mcq', 'Điền từ danh từ hóa động từ: 日本語で作文を（　）のは楽しいです。', '["書いて", "書きます", "書く", "書いた"]'::jsonb, 2, null, 'trim_only', 'Trước の để danh từ hóa dùng động từ thể từ điển / thông thường.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000096', '10000000-0000-0000-0000-000000000048', 1, 'cloze', '料理を作る（　）が上手ですね。', null, null, '["の"]'::jsonb, 'trim_only', 'Động từ 作る + の làm chủ ngữ cho 上手.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000097', '10000000-0000-0000-0000-000000000049', 1, 'mcq', 'Chọn đúng hình thức trước に của động từ di chuyển: 友達と映画を（　）に行きます。', '["見る", "見て", "見た", "見"]'::jsonb, 3, null, 'trim_only', 'Động từ đứng trước に chỉ mục đích phải bỏ ます (見ます -> 見).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000098', '10000000-0000-0000-0000-000000000049', 1, 'cloze', '公園へ散歩（　）行きませんか。', null, null, '["に"]'::jsonb, 'trim_only', 'Danh từ hoặc V(ます bỏ ます) kết hợp に + 行く.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000099', '10000000-0000-0000-0000-000000000050', 1, 'mcq', 'Chọn động từ khi người khác tặng cho mình: 兄が私に辞書を（　）。', '["くれました", "あげました", "もらいました", "しました"]'::jsonb, 0, null, 'trim_only', 'Khi chủ ngữ là người khác tặng cho 私, dùng くれます / くれました.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000100', '10000000-0000-0000-0000-000000000050', 1, 'cloze', '私は先生に本を（　）。（Tôi nhận sách từ thầy）', null, null, '["もらいました"]'::jsonb, 'trim_only', 'Tôi nhận từ ai dùng 私 は [người] に 〜 を もらう.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000101', '10000000-0000-0000-0000-000000000051', 1, 'mcq', 'Chọn dạng động từ đúng: 日本へ（　）まえに、ひらがなを覚えました。', '["行った", "行く", "行って", "行きます"]'::jsonb, 1, null, 'trim_only', 'Dù cả câu ở quá khứ, động từ ngay trước まえに vẫn giữ thể từ điển (行く).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000102', '10000000-0000-0000-0000-000000000051', 1, 'cloze', '授業（　）まえに、テキストを読んでおきます。', null, null, '["の"]'::jsonb, 'trim_only', 'Trước まえに nếu là danh từ phải có trợ từ の.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000103', '10000000-0000-0000-0000-000000000052', 1, 'mcq', 'Chọn thể khả năng của 話す: ミラーさんは日本語が上手に（　）。', '["話します", "話せます", "話させます", "話されます"]'::jsonb, 1, null, 'trim_only', '話す (nhóm I) chuyển đuôi u sang e + る thành 話せる -> 話せます.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000104', '10000000-0000-0000-0000-000000000052', 1, 'cloze', '目が悪くて、小さい字が（　）ません。', null, null, '["読め"]'::jsonb, 'trim_only', '読む chia thể khả năng là 読める -> 読めません.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000105', '10000000-0000-0000-0000-000000000053', 1, 'mcq', 'Chọn thể phù hợp với ngữ cảnh phòng đã được chuẩn bị sẵn: 部屋の窓が（　）。', '["開いてあります", "開けてあります", "開けています", "開きました"]'::jsonb, 1, null, 'trim_only', '〜てある đi với tha động từ (開ける -> 開けてある) nêu trạng thái có chủ ý.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000106', '10000000-0000-0000-0000-000000000053', 1, 'cloze', '黒板に今日の予定が書い（　）あります。', null, null, '["て"]'::jsonb, 'trim_only', '書く -> 書いて + あります.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000107', '10000000-0000-0000-0000-000000000054', 1, 'mcq', 'Chọn mẫu ''làm sẵn trước'': 客が来ますから、部屋を掃除して（　）。', '["います", "おきます", "みます", "しまいます"]'::jsonb, 1, null, 'trim_only', 'Chuẩn bị sẵn sàng cho việc sắp tới dùng Vて + おきます.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000108', '10000000-0000-0000-0000-000000000054', 1, 'cloze', '明日の授業のために、単語を調べ（　）おきました。', null, null, '["て"]'::jsonb, 'trim_only', '調べる -> 調べて + おく.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000109', '10000000-0000-0000-0000-000000000055', 1, 'mcq', 'Chọn mẫu diễn tả sự lỡ quên đáng tiếc: 大切な約束を（　）。', '["忘れてしまいました", "忘れておきました", "忘れてみました", "忘れてありました"]'::jsonb, 0, null, 'trim_only', 'Sự việc đáng tiếc hoặc hoàn tất dứt điểm dùng Vて + しまう.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000110', '10000000-0000-0000-0000-000000000055', 1, 'cloze', '宿題はさっき全部やって（　）ました。', null, null, '["しまい"]'::jsonb, 'trim_only', 'やって + しまいました diễn tả đã làm xong hoàn toàn.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000111', '10000000-0000-0000-0000-000000000056', 1, 'mcq', 'Chọn đuôi phù hợp với bối cảnh ''gần đây trời trở lạnh dần tới nay'': 最近、寒く（　）。', '["なっていきました", "なりましたから", "なってきました", "なっていました"]'::jsonb, 2, null, 'trim_only', 'Biến đổi bắt đầu từ quá khứ tiến tới hiện tại dùng 〜てきました.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000112', '10000000-0000-0000-0000-000000000056', 1, 'cloze', 'これからも健康に気をつけ（　）いきます。', null, null, '["て"]'::jsonb, 'trim_only', 'Tiếp diễn hướng về tương lai dùng Vて + いく.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000113', '10000000-0000-0000-0000-000000000057', 1, 'mcq', 'Chọn cách kết hợp đúng cho ''bắt đầu học'': 先月から日本語を（　）。', '["習いはじめました", "習うはじめました", "習ってはじめました", "習ったはじめました"]'::jsonb, 0, null, 'trim_only', 'Trước はじめる / おわる dùng động từ bỏ ます (習います -> 習い).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000114', '10000000-0000-0000-0000-000000000057', 1, 'cloze', 'ご飯を食べ（　）から、コーヒーを飲みましょう。', null, null, '["おわって", "終わって"]'::jsonb, 'trim_only', 'Làm xong việc gì rồi làm tiếp dùng Vます + おわって.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000115', '10000000-0000-0000-0000-000000000058', 1, 'mcq', 'Chọn đúng dạng nối với つづける: 同じ会社で十年（　）。', '["働くつづけている", "働きつづけている", "働いてつづけている", "働かつづけている"]'::jsonb, 1, null, 'trim_only', 'Động từ gốc ます bỏ ます + つづける (働きます -> 働きつづける).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000116', '10000000-0000-0000-0000-000000000058', 1, 'cloze', '雨が朝からずっと降り（　）ています。', null, null, '["つづけ", "続け"]'::jsonb, 'trim_only', '降ります bỏ ます cộng つづけています.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000117', '10000000-0000-0000-0000-000000000059', 1, 'mcq', 'Chọn mẫu nhấn mạnh cảm giác ''mới vừa'': 去年、大学を（　）ばかりです。', '["卒業する", "卒業した", "卒業して", "卒業しよう"]'::jsonb, 1, null, 'trim_only', '〜たばかり đứng sau động từ thể た.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000118', '10000000-0000-0000-0000-000000000059', 1, 'cloze', 'この靴は先週買っ（　）ばかりなのに、もう壊れました。', null, null, '["た"]'::jsonb, 'trim_only', '買う đổi sang thể た thành 買った + ばかり.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000119', '10000000-0000-0000-0000-000000000060', 1, 'mcq', 'Chọn câu nghĩa ''vừa mới nấu xong ngay lúc này'': ケーキが今（　）。', '["できたところです", "できるところです", "できているところです", "できそうです"]'::jsonb, 0, null, 'trim_only', 'Hành động vừa hoàn tất ngay tức khắc dùng Vた + ところです.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000120', '10000000-0000-0000-0000-000000000060', 1, 'cloze', '今、友達にメールを送ってい（　）ところです。', null, null, '["る"]'::jsonb, 'trim_only', 'Đang ngay giữa lúc làm hành động dùng Vている + ところ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000121', '10000000-0000-0000-0000-000000000061', 1, 'mcq', 'Chọn mẫu đúng: 朝ご飯を（　）、学校へ来てしまいました。', '["食べないで", "食べなくて", "食べなく", "食べたから"]'::jsonb, 0, null, 'trim_only', 'Làm hành động chính mà không thực hiện hành động trước dùng Vないで.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000122', '10000000-0000-0000-0000-000000000061', 1, 'cloze', '砂糖を入れ（　）コーヒーを飲みます。', null, null, '["ないで"]'::jsonb, 'trim_only', '入らない/入れない -> 入れないで mang nghĩa ''không bỏ vào mà uống''.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000123', '10000000-0000-0000-0000-000000000062', 1, 'mcq', 'Chọn dạng đúng của する với ずに: メモを（　）、全部覚えました。', '["しないずに", "しずに", "せずに", "せずで"]'::jsonb, 2, null, 'trim_only', 'Ngoại lệ của 〜ずに là する chuyển thành せずに.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000124', '10000000-0000-0000-0000-000000000062', 1, 'cloze', '昨日は勉強せ（　）寝てしまいました。', null, null, '["ずに"]'::jsonb, 'trim_only', 'する kết hợp ずに luôn biến thành せずに.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000125', '10000000-0000-0000-0000-000000000063', 1, 'mcq', 'Chọn vế sau đúng cho điều kiện tất yếu ～と: まっすぐ行くと、（　）。', '["左に銀行があります", "左を見てください", "銀行へ行きましょう", "写真を撮りたいです"]'::jsonb, 0, null, 'trim_only', 'Với điều kiện tất yếu ～と, vế sau là sự thật khách quan chứ không phải mệnh lệnh hay ý định.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000126', '10000000-0000-0000-0000-000000000063', 1, 'cloze', '夜遅くまで起きている（　）、朝起きられません。', null, null, '["と"]'::jsonb, 'trim_only', 'Hệ quả tự nhiên/thường thấy nối bằng と.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000127', '10000000-0000-0000-0000-000000000064', 1, 'mcq', 'Chọn thể đúng với たら: 時間が（　）、映画を見に行きませんか。', '["あるたら", "ありたら", "あったら", "あってら"]'::jsonb, 2, null, 'trim_only', 'Quá khứ thông thường của ある là あった kết hợp ら thành あったら.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000128', '10000000-0000-0000-0000-000000000064', 1, 'cloze', '日本へ来（　）、ぜひ富士山を見たいです。', null, null, '["たら"]'::jsonb, 'trim_only', '来る -> 来た + ら (来たら).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000129', '10000000-0000-0000-0000-000000000065', 1, 'mcq', 'Chọn thể điều kiện ば đúng của 読む: よく（　）、意味がわかります。', '["読めば", "読むば", "読みば", "読んでば"]'::jsonb, 0, null, 'trim_only', '読む đổi âm cuối u thành e + ば -> 読めば.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000130', '10000000-0000-0000-0000-000000000065', 1, 'cloze', '安（　）、そのパソコンを買いたいです。', null, null, '["ければ"]'::jsonb, 'trim_only', 'Tính từ い (安い) bỏ い cộng ければ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000131', '10000000-0000-0000-0000-000000000066', 1, 'mcq', 'Chọn từ điều kiện theo chủ đề người khác nêu: ''東京へ行きたいです'' — ''東京へ行く（　）、新幹線が便利です。''', '["と", "なら", "たら", "から"]'::jsonb, 1, null, 'trim_only', 'Tiếp nhận chủ đề đối phương nêu ra để khuyên dùng なら.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000132', '10000000-0000-0000-0000-000000000066', 1, 'cloze', '日本料理（　）、やはり寿司がおいしいです。', null, null, '["なら"]'::jsonb, 'trim_only', 'Danh từ đi trực tiếp với なら để nêu chủ đề.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000133', '10000000-0000-0000-0000-000000000067', 1, 'mcq', 'Chọn cách gợi ý đúng: そんなに疲れているなら、早く（　）。', '["寝たらどうですか", "寝てどうですか", "寝るどうですか", "寝ますか"]'::jsonb, 0, null, 'trim_only', 'Mẫu khuyên gợi ý là Vた + らどうですか.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000134', '10000000-0000-0000-0000-000000000067', 1, 'cloze', '一度病院へ（　）どうですか。', null, null, '["行ったら"]'::jsonb, 'trim_only', '行く đổi sang thể た + ら thành 行ったら.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000135', '10000000-0000-0000-0000-000000000068', 1, 'mcq', 'Chọn dạng liên kết đúng với ので: 明日は（　）、早く帰ります。', '["雨ので", "雨なので", "雨から", "雨だので"]'::jsonb, 1, null, 'trim_only', 'Danh từ và tính từ đuôi な đứng trước ので phải thêm な.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000136', '10000000-0000-0000-0000-000000000068', 1, 'cloze', '急用ができた（　）、失礼します。', null, null, '["ので"]'::jsonb, 'trim_only', 'Mệnh đề động từ thông thường + ので diễn tả lý do lịch sự.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000137', '10000000-0000-0000-0000-000000000069', 1, 'mcq', 'Chọn từ nối mang sắc thái ngạc nhiên/tiếc nuối: 薬を飲んだ（　）、まだ熱が下がりません。', '["ので", "から", "のに", "たら"]'::jsonb, 2, null, 'trim_only', 'Kết quả trái mong đợi kèm cảm giác thất vọng dùng のに.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000138', '10000000-0000-0000-0000-000000000069', 1, 'cloze', '一生懸命勉強した（　）、テストに落ちてしまいました。', null, null, '["のに"]'::jsonb, 'trim_only', 'Dù đã cố gắng nhưng kết quả trái ý -> のに.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000139', '10000000-0000-0000-0000-000000000070', 1, 'mcq', 'Chọn dạng nhượng bộ đúng cho danh từ: （　）、仕事があります。', '["日曜日ても", "日曜日くても", "日曜日でも", "日曜日でても"]'::jsonb, 2, null, 'trim_only', 'Danh từ và tính từ đuôi な kết hợp でも để nói ''dù là''.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000140', '10000000-0000-0000-0000-000000000070', 1, 'cloze', '何度聞いて（　）、よくわかりません。', null, null, '["も"]'::jsonb, 'trim_only', 'Động từ thể て + も mang nghĩa ''cho dù đã làm... vẫn...''.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000141', '10000000-0000-0000-0000-000000000071', 1, 'mcq', 'Chọn dạng đúng của tính từ な trước し: この店は料理がおいしいし、店員も（　）。', '["親切だし", "親切し", "親切なし", "親切でし"]'::jsonb, 0, null, 'trim_only', 'Danh từ và tính từ đuôi な thể thông thường trước し dùng だ (親切だし).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000142', '10000000-0000-0000-0000-000000000071', 1, 'cloze', '宿題も多い（　）、アルバイトもあります。', null, null, '["し"]'::jsonb, 'trim_only', 'Liệt kê thêm lý do dùng trợ từ し.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000143', '10000000-0000-0000-0000-000000000072', 1, 'mcq', 'Chọn mẫu chỉ nguyên nhân dẫn đến cảm xúc: あなたに会えて、（　）。', '["うれしいです", "会いましょう", "来てください", "行くつもりです"]'::jsonb, 0, null, 'trim_only', 'Vế sau của mẫu nguyên nhân ～て chỉ cảm xúc hoặc trạng thái tự nhiên, không dùng ý chí.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000144', '10000000-0000-0000-0000-000000000072', 1, 'cloze', '風邪をひい（　）、頭が痛いです。', null, null, '["て"]'::jsonb, 'trim_only', 'Nguyên nhân nhẹ gây trạng thái đau đầu dùng thể て.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000145', '10000000-0000-0000-0000-000000000073', 1, 'mcq', 'Chọn dạng kết hợp đúng với すぎる: このテストは（　）て、全然できません。', '["難しいすぎ", "難しすぎ", "難しくすぎ", "難しいなすぎ"]'::jsonb, 1, null, 'trim_only', 'Tính từ đuôi い bỏ い rồi cộng すぎる (難しい -> 難しすぎる).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000146', '10000000-0000-0000-0000-000000000073', 1, 'cloze', '甘いものを食べ（　）ないように気をつけます。', null, null, '["すぎ", "過ぎ"]'::jsonb, 'trim_only', '食べます bỏ ます cộng すぎない.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000147', '10000000-0000-0000-0000-000000000074', 1, 'mcq', 'Chọn cấu trúc diễn tả ''rất dễ hiểu'': 先生の説明はとても（　）。', '["わかりにくい", "わかりやすい", "わかるやすい", "わかってやすい"]'::jsonb, 1, null, 'trim_only', 'Động từ gốc ます (わかり) + やすい diễn tả sự dễ dàng.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000148', '10000000-0000-0000-0000-000000000074', 1, 'cloze', 'この靴は軽くて歩き（　）です。', null, null, '["やすい"]'::jsonb, 'trim_only', 'Nghĩa ''dễ đi lại'' dùng Vます + やすい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000149', '10000000-0000-0000-0000-000000000075', 1, 'mcq', 'Chọn dạng đúng cho động từ: 荷物が（　）そうですから、気をつけて。', '["落ち", "落ちる", "落ちた", "落ちて"]'::jsonb, 0, null, 'trim_only', 'Trông sắp xảy ra dùng Vます bỏ ます + そうだ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000150', '10000000-0000-0000-0000-000000000075', 1, 'cloze', '雲が黒くて、雨が降り（　）ですね。', null, null, '["そう"]'::jsonb, 'trim_only', 'Quan sát thấy dấu hiệu sắp mưa -> 降りそうです.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000151', '10000000-0000-0000-0000-000000000076', 1, 'mcq', 'Chọn đúng cách diễn tả mong muốn của bạn A: リンさんは日本へ（　）。', '["行きたがっています", "行きたいです", "行ってほしいです", "行くつもり"]'::jsonb, 0, null, 'trim_only', 'Nói về mong muốn ngôi thứ ba dùng 〜たがっている.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000152', '10000000-0000-0000-0000-000000000076', 1, 'cloze', '寒いので、犬が外へ出た（　）ません。', null, null, '["がり"]'::jsonb, 'trim_only', '〜たがる chia phủ định thành 〜たがりません.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000153', '10000000-0000-0000-0000-000000000077', 1, 'mcq', 'Chọn mẫu ''thử làm'': おいしいかどうか、飲んで（　）ましょう。', '["おき", "み", "しまい", "あり"]'::jsonb, 1, null, 'trim_only', 'Thử làm để biết cảm nhận dùng Vて + みる.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000154', '10000000-0000-0000-0000-000000000077', 1, 'cloze', 'わからないときは、自分で考え（　）みてください。', null, null, '["て"]'::jsonb, 'trim_only', '考える -> 考えて + みる.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000155', '10000000-0000-0000-0000-000000000078', 1, 'mcq', 'Chọn dạng đúng trước なさい: 毎日もっと野菜を（　）なさい。', '["食べる", "食べて", "食べ", "食べた"]'::jsonb, 2, null, 'trim_only', 'Cấu trúc mệnh lệnh nhẹ dùng Vます bỏ ます + なさい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000156', '10000000-0000-0000-0000-000000000078', 1, 'cloze', '教室に入ったら、静かに座り（　）。', null, null, '["なさい"]'::jsonb, 'trim_only', 'Thể gốc ます (座ります) thay ます bằng なさい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000157', '10000000-0000-0000-0000-000000000079', 1, 'mcq', 'Chọn mẫu ''muốn ai làm gì'': 私は弟にもっと勉強（　）。', '["してほしいです", "したいです", "してほしいで", "してあげたい"]'::jsonb, 0, null, 'trim_only', 'Mong người khác làm cho dùng [Người] に Vて + ほしい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000158', '10000000-0000-0000-0000-000000000079', 1, 'cloze', '忙しいときに、誰かに手伝っ（　）ほしいです。', null, null, '["て"]'::jsonb, 'trim_only', '手伝う -> 手伝って + ほしい.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000159', '10000000-0000-0000-0000-000000000080', 1, 'mcq', 'Chọn thể ý chí đúng của 行く: 来年、東京へ（　）と思っています。', '["行くよう", "行こう", "行けよう", "行ったよう"]'::jsonb, 1, null, 'trim_only', 'Nhóm I 行く đổi âm u sang o + う -> 行こう.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000160', '10000000-0000-0000-0000-000000000080', 1, 'cloze', 'もっと健康のために毎日歩こ（　）と思います。', null, null, '["う"]'::jsonb, 'trim_only', '歩こう dùng đuôi う ở thể ý chí.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000161', '10000000-0000-0000-0000-000000000081', 1, 'mcq', 'Chọn cách kết hợp đúng với danh từ: 来週は京都（　）予定です。', '["旅行するな", "旅行の", "旅行だ", "旅行に"]'::jsonb, 1, null, 'trim_only', 'Danh từ đứng trước 予定 cần trợ từ の.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000162', '10000000-0000-0000-0000-000000000081', 1, 'cloze', '飛行機は午後三時に到着する（　）です。', null, null, '["予定"]'::jsonb, 'trim_only', 'Động từ thể từ điển + 予定です diễn tả lịch trình.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000163', '10000000-0000-0000-0000-000000000082', 1, 'mcq', 'Chọn câu thể hiện quyết định từ công ty/tập thể: 会議で新しいルールを作る（　）。', '["ことにしました", "ことになりました", "つもりです", "ようです"]'::jsonb, 1, null, 'trim_only', 'Quyết định khách quan từ tập thể dùng 〜ことになる.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000164', '10000000-0000-0000-0000-000000000082', 1, 'cloze', 'もう遅いから、今日はここで帰る（　）にします。', null, null, '["こと"]'::jsonb, 'trim_only', 'Tự bản thân quyết định dùng ことにする.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000165', '10000000-0000-0000-0000-000000000083', 1, 'mcq', 'Chọn dạng đúng trước と思う: この映画はとてもおもしろい（　）思います。', '["だ", "と", "を", "が"]'::jsonb, 1, null, 'trim_only', 'Trích dẫn nội dung suy nghĩ luôn dùng trợ từ と.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000166', '10000000-0000-0000-0000-000000000083', 1, 'cloze', '彼はおそらくもう駅に着いた（　）思います。', null, null, '["と"]'::jsonb, 'trim_only', 'Thể thông thường + と + と思う.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000167', '10000000-0000-0000-0000-000000000084', 1, 'mcq', 'Chọn đúng hình thức tường thuật: 友達は「また明日」と（　）。', '["思いました", "言いました", "聞きました", "話しました"]'::jsonb, 1, null, 'trim_only', 'Thuật lại câu nói trực tiếp trong dấu ngoặc dùng と言いました.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000168', '10000000-0000-0000-0000-000000000084', 1, 'cloze', '母は体に気をつけなさい（　）言いました。', null, null, '["と"]'::jsonb, 'trim_only', 'Trước 言いました dùng trợ từ trích dẫn と.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000169', '10000000-0000-0000-0000-000000000085', 1, 'mcq', 'Chọn mẫu ''có đúng không/có hay không'': 鍵をかけた（　）忘れてしまいました。', '["か", "かどうか", "のか", "ところ"]'::jsonb, 1, null, 'trim_only', 'Nghi vấn dạng có/không trong câu ghép dùng かどうか.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000170', '10000000-0000-0000-0000-000000000085', 1, 'cloze', 'サイズが合う（　）どうか、履いてみてください。', null, null, '["か"]'::jsonb, 'trim_only', 'Cụm かどうか gắn sau thể thông thường.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000171', '10000000-0000-0000-0000-000000000086', 1, 'mcq', 'Chọn từ nối đúng sau danh từ chỉ mục đích: 将来（　）ために、毎日貯金しています。', '["の", "な", "に", "で"]'::jsonb, 0, null, 'trim_only', 'Danh từ đứng trước ために phải thêm trợ từ の.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000172', '10000000-0000-0000-0000-000000000086', 1, 'cloze', '日本語が上手になる（　）、毎日ニュースを聞いています。', null, null, '["ために"]'::jsonb, 'trim_only', 'Động từ có chủ ý đạt mục tiêu đi với ために.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000173', '10000000-0000-0000-0000-000000000087', 1, 'mcq', 'Chọn mẫu đúng với động từ khả năng/phủ định: 遅刻（　）ように、早く家を出ます。', '["する", "しない", "した", "して"]'::jsonb, 1, null, 'trim_only', 'Mục tiêu tránh điều ngoài ý muốn dùng Vない + ように.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000174', '10000000-0000-0000-0000-000000000087', 1, 'cloze', '後ろの人にも聞こえる（　）、大きい声で話します。', null, null, '["ように"]'::jsonb, 'trim_only', 'Động từ 聞こえる (không chủ ý) đi với ように.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000175', '10000000-0000-0000-0000-000000000088', 1, 'mcq', 'Chọn mẫu khi bạn được người khác giúp đỡ: 友達が駅まで車で送って（　）。', '["くれました", "あげました", "もらいました", "しました"]'::jsonb, 0, null, 'trim_only', 'Chủ ngữ là 友達 làm hành động giúp tôi dùng てくれた / てくれました.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000176', '10000000-0000-0000-0000-000000000088', 1, 'cloze', '私は妹の宿題を手伝っ（　）あげました。', null, null, '["て"]'::jsonb, 'trim_only', '手伝う -> 手伝って + あげる.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000177', '10000000-0000-0000-0000-000000000089', 1, 'mcq', 'Chọn thể bị động đúng của 叱る: 遅刻して、課長に（　）。', '["叱りました", "叱らせました", "叱られました", "叱れました"]'::jsonb, 2, null, 'trim_only', '叱る (nhóm I) chia bị động thành 叱られる -> 叱られました.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000178', '10000000-0000-0000-0000-000000000089', 1, 'cloze', '雨に降ら（　）、服がぬれてしまいました。', null, null, '["れて"]'::jsonb, 'trim_only', 'Bị động của 降る là 降られる -> 降られて (bị dính mưa).') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000179', '10000000-0000-0000-0000-000000000090', 1, 'mcq', 'Chọn cách kết hợp đúng sau danh từ: 次のバスが最終（　）しれません。', '["だかも", "のかも", "かも", "なかも"]'::jsonb, 2, null, 'trim_only', 'Danh từ và tính từ đuôi な đi thẳng với かもしれない, không dùng だ.') on conflict (id) do nothing;
insert into public.practice_questions (id, grammar_id, content_version, question_type, prompt, options, correct_option_index, accepted_answers, normalization, explanation_vi) values ('20000000-0000-0000-0000-000000000180', '10000000-0000-0000-0000-000000000090', 1, 'cloze', '道が込んでいるので、少し遅れる（　）しれません。', null, null, '["かも"]'::jsonb, 'trim_only', 'Cụm かもしれない diễn tả khả năng có thể xảy ra.') on conflict (id) do nothing;
